import { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";
import "../styles/ChatMessage.css"; // tên đúng file bạn gửi
import "../styles/ChatInput.css";

export default function ChatMain() {
  const { id } = useParams();
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([
    {
      id: 1, text: `Hello! I'm your AI assistant. 💙`, isUser: false,
      timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    },
  ]);
  const listRef = useRef(null);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, id]);

  const handleSend = (e) => {
    e?.preventDefault();
    if (!text.trim()) return;
    const now = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    setMessages((prev) => [
      ...prev,
      { id: Date.now(), text, isUser: true, timestamp: now },
    ]);
    setText("");
  };

  return (
    <div className="chat-main">
      {/* khớp App.css: messages-container > messages-list */}
      <div className="messages-container">
        <div ref={listRef} className="messages-list">
          {messages.map((m) => (
            <div key={m.id} className={`message ${m.isUser ? "user-message" : "ai-message"}`}>
              <div className="message-avatar"><span>{m.isUser ? "U" : "AI"}</span></div>
              <div className="message-content">
                <div className="message-bubble">{m.text}</div>
                <div className="message-timestamp">{m.timestamp}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <form className="chat-input-form" onSubmit={handleSend}>
        <div className="input-container">
          <input
            className="message-input"
            type="text"
            placeholder="Type your message..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <button className="send-button" type="submit" disabled={!text.trim()}>
            <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true">
              <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
            </svg>
          </button>
        </div>
      </form>
    </div>
  );
}
